insert into public.shop_items (id, kind, name, description, price, payload, icon, accent, active, sort_order) values
('cosmetic.aura.veu_carmesim','cosmetic','Aura do Véu Carmesim','Um anel de névoa rubra e pétalas em brasa gira ao redor do avatar, com um eclipse negro coroando o topo. A marca de quem atravessou o crepúsculo.',750,'{"key":"veu_carmesim","slot":"decoration"}','sparkles','crimson',true,310),
('cosmetic.frame.coroa_crepusculo','cosmetic','Coroa do Crepúsculo','Moldura de prata escurecida com espinhos, rosas rubras e uma gema de eclipse cravada no centro. Ornamento de realeza sob o sol morto.',700,'{"key":"coroa_crepusculo","slot":"nameplate"}','crown','crimson',true,311),
('cosmetic.effect.catedral_eclipse','cosmetic','Catedral do Eclipse','Capa de perfil: ruínas góticas sob um eclipse carmesim, roseiral em chamas frias e vitrais pulsando em vermelho profundo.',800,'{"key":"catedral_eclipse","slot":"effect"}','moon','crimson',true,312),
('cosmetic.overlay.rosas_crepusculo','cosmetic','Rosas do Crepúsculo','Overlay animado: uma chuva lenta de pétalas rubras cai por cima da sua capa, com brilho quente nas bordas.',600,'{"key":"rosas_crepusculo","slot":"overlay"}','sparkles','crimson',true,313),
('cosmetic.veil.veu_rubro','cosmetic','Véu Rubro','Moldura de cartão com renda carmesim se desfazendo em espinhos e rubis engastados — o segundo véu da soberana do eclipse.',650,'{"key":"veu_rubro","slot":"veil"}','moon','crimson',true,314),
('cosmetic.companion.corvo_carmesim','cosmetic','Corvo do Crepúsculo','Companheiro: um corvo espiritual de asas rubras, olhos de eclipse e pétalas presas nas penas. Arauto do fim da luz.',900,'{"key":"corvo_carmesim","slot":"companion"}','sparkles','crimson',true,315),
('bundle.eclipse_carmesim','bundle','Eclipse Carmesim','Quando o sol morre atrás da lua, o Reino Carmesim acorda. A coleção Eclipse Carmesim reúne cosméticos nascidos do crepúsculo eterno: catedrais em ruínas, rosas que sangram luz, véus de renda rubra e uma soberana coroada pelo sol negro. Elegância gótica para quem encontra beleza no último instante do dia.',1100,'{"items":["cosmetic.effect.catedral_eclipse","cosmetic.overlay.rosas_crepusculo","cosmetic.aura.veu_carmesim","cosmetic.frame.coroa_crepusculo","cosmetic.veil.veu_rubro","cosmetic.companion.corvo_carmesim"]}','crown','crimson',true,7)
